 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_pubofrRslt_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_pubofrRslt_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.pubofrRslt('' + dma_pageContext.get("bzProcsNo") + '','' + dma_pageContext.get("isurCd") + '')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil55100n.btn_pubofrRslt_onclick' }); }
};

