/**
 * @method
 * @name scwin.checkListDd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkListDd = async function () {
    /* sdd-asis-lifecycle:begin fn_checkListDd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */


    scwin.xmlhttp = scwin.GetXmlHttpObject();

    if (scwin.xmlhttp == null) {
        await $c.win.alert ("Ajax를 지원하지 않는 브라우저입니다.\n 헬프데스크에 문의하시기 바랍니다!");
        return;
    }

    const frm = $c.util.getComponent('pubofrRsltForm');
    const listSchdlDd = $c.util.getComponent('ipt_listSchdlDd').getValue();
    if(($c.util.getComponent('ipt_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('ipt_listSchdlDd').getValue())) === ''){
        await $c.win.alert('상장(희망)일을 입력하십시오');
        return;

    }

    //KBoY 2014-12-03 SrM-000090012 201412만 중복 신청 가능.
    if(is201412(listSchdlDd)){
        await $c.win.alert('신청 가능한 희망일입니다.');
        $c.util.getComponent("dma_registerReq").set("possibleYn", 'Y');
    }else{
        const url="/listInvstg/pubOfrSchdl.do?method=checkListDd&listSchdlDd=" + listSchdlDd + "&bzProcsNo="+"" + dma_pageContext.get("bzProcsNo") + "";
        scwin.xmlhttp.onreadystatechange=scwin.stateChanged;
        scwin.xmlhttp.open("POST",url,true);
        scwin.xmlhttp.send(null);
    }

    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.stateChanged
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.stateChanged = async function () {
    /* sdd-asis-lifecycle:begin stateChanged — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = $c.util.getComponent('pubofrRsltForm');
    if (scwin.xmlhttp.readyState == 4) {
        const returnText = scwin.trim(scwin.xmlhttp.responseText);
        if (returnText === 'N') {
            await $c.win.alert('이미 신청중인 상장(희망)일입니다.\n 다른 날짜를 선택해 주십시오.');
            $c.util.getComponent("ipt_listSchdlDd").setValue('');
        } else {
            await $c.win.alert('신청 가능한 희망일입니다.');
            $c.util.getComponent("dma_registerReq").set("possibleYn", 'Y');
        }
    }
    /* sdd-asis-lifecycle:end */
};


