/**
 * @method
 * @name scwin.trim
 * @author Inswave
 * @date 2026. 09. 29
 * @param str
 * @returns
 * @hidden N
*/
scwin.trim = function (str) {
    /* sdd-asis-lifecycle:begin trim — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    str = str.replace(/^\s*/, '').replace(/\s*$/, '');
    return str;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkNumber
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.checkNumber = async function (obj) {
    /* sdd-asis-lifecycle:begin fn_checkNumber — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (/[^0123456789.]/g.test(obj.value)) {
        await $c.win.alert("숫자가 아닙니다.\n\n0-9의 정수만 허용합니다.");
        obj.select();
        return;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkNumber1
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.checkNumber1 = async function (obj) {
    /* sdd-asis-lifecycle:begin fn_checkNumber1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (/[^0123456789.]/g.test(obj.value)) {
        await $c.win.alert("숫자가 아닙니다.\n\n0-9의 정수만 허용합니다.");
        obj.select();
        return;
    }
    if (parseFloat(obj.value) > 100) {
        await $c.win.alert('100% 이하 소수로 입력하시기 바랍니다.');
        obj.select();
        return;
    }
    if (obj.value.indexOf(".") > 0) {
        if (obj.value.substring(obj.value.indexOf(".") + 1).length > 6) {
            await $c.win.alert('소수 6자리까지 입력할 수 있습니다');
            obj.select();
            return;
        }
    } else {
        if (obj.value.length > 3) {
            await $c.win.alert('100% 이하 소수로 입력하시기 바랍니다.');
            obj.select();
            return;
        }
    }
    /* sdd-asis-lifecycle:end */
};
